    }









    @Test
    public void testRead_ReturnsMinusOneAtEOF() throws IOException {
        byte[] content = "Small".getBytes(StandardCharsets.UTF_8);
        byte[] tarData = createMockTarStream("test.txt", content);
        InputStream is = new ByteArrayInputStream(tarData);
        TarArchiveInputStream tais = new TarArchiveInputStream(is);

        tais.getNextTarEntry();

        // Read all content
        byte[] buf = new byte[10];
        tais.read(buf, 0, 5);
        tais.read(buf, 0, 5); // This might reach EOF depending on content length/padding

        // Exhaust the stream
        int lastRead = -1;
        while ((lastRead = tais.read(new byte[1], 0, 1)) != -1);

        // Now hasHitEOF should be true
        byte[] buf2 = new byte[5];
        int result = tais.read(buf2, 0, 5);
        Assert.assertEquals(-1, result);
    }


}

